// ---------- 钉钉（dws CLI）：把钉钉文档/知识库接进面板 ----------
// dws 是钉钉官方命令行工具，OAuth device-flow 登录（每人各自登录），全程走钉钉开放平台 + 审计。
// 这里只做「读」：列知识库 / 列节点 / 读正文(markdown) / 搜索；写回交给终端里的 agent（带确认）。
let DWS_BIN = PLATFORM === 'win32' ? 'dws.exe' : 'dws';
try {
  const probe = PLATFORM === 'win32' ? 'where dws' : 'command -v dws';
  const found = require('child_process').execSync(probe, { encoding: 'utf8' }).trim().split(/\r?\n/)[0];
  if (found) DWS_BIN = found;
} catch { /* 未安装 dws：调用时回友好错误 */ }

// 调 dws 并解析输出。默认 -f json：成功是 JSON 对象，业务错误是 { error: {...} }。
// 绝对路径 + execFile（无 shell）杜绝命令注入；id 类参数再过一层白名单。
function runDws(args) {
  return new Promise((resolve) => {
    execFile(DWS_BIN, args, { timeout: 30000, maxBuffer: 16 * 1024 * 1024, windowsHide: true, env: { ...process.env } }, (err, stdout, stderr) => {
      const raw = (stdout || '').trim();
      if (raw) {
        let data;
        try { data = JSON.parse(raw); } catch { return resolve({ ok: true, data: { raw } }); }
        if (data && data.error) return resolve({ ok: false, error: data.error.message || 'dws 返回错误', detail: data.error });
        return resolve({ ok: true, data });
      }
      const msg = (stderr || (err && err.message) || 'dws 无输出').trim();
      resolve({ ok: false, error: /ENOENT/.test(msg) ? '未找到 dws，请先安装并执行 dws auth login' : msg });
    });
  });
}
