function runDws(args) {
  return new Promise((resolve) => {
    execFile(DWS_BIN, args, { timeout: 30000, maxBuffer: 16 * 1024 * 1024, windowsHide: true, env: { ...process.env } }, (err, stdout, stderr) => {
      const raw = (stdout || '').trim();
      if (raw) {
        let data;
        try { data = JSON.parse(raw); } catch { return resolve({ ok: true, data: { raw } }); }
        if (data && data.error) return resolve({ ok: false, error: data.error.message || 'dws 返回错误', detail: data.error });
        return resolve({ ok: true, data });
      }
      // 业务错误：dws 把 { error: {...} } 写到 stderr 且 stdout 空，抽出 message 给前端
      const errRaw = (stderr || '').trim();
      if (errRaw) {
        try { const e = JSON.parse(errRaw); if (e && e.error) return resolve({ ok: false, error: e.error.message || 'dws 返回错误', detail: e.error }); } catch { /* 非 JSON，原样回 */ }
        return resolve({ ok: false, error: /ENOENT/.test(errRaw) ? '未找到 dws，请先安装并执行 dws auth login' : errRaw });
      }
      const msg = ((err && err.message) || 'dws 无输出').trim();
      resolve({ ok: false, error: /ENOENT/.test(msg) ? '未找到 dws，请先安装并执行 dws auth login' : msg });
    });
  });
}

